const input = $json;
const err = input.execution?.error || input.error || input;
const workflow = input.workflow?.name || input.workflowName || input.engine || 'UNKNOWN_WORKFLOW';
const message = err.message || err.description || input.text || 'Unknown n8n error';
const node = input.execution?.lastNodeExecuted || input.node?.name || input.nodeName || 'UNKNOWN_NODE';
const severity = /credential|auth|unauthorized|forbidden|timeout|rate/i.test(message) ? 'HIGH' : 'MEDIUM';
return [{ json: {
  skill: 'ERROR_GUARDIAN',
  status: 'ERROR_CAPTURED',
  severity,
  workflow,
  node,
  error_message: message,
  summary: `${severity} issue in ${workflow} at ${node}: ${message}`,
  actions: [
    'Keep workflow in degraded mode where possible; do not expose secrets in logs.',
    'Check credential validity and recent node changes first.',
    'Re-run the affected workflow with a small health-check payload after remediation.'
  ],
  next_step: 'Open the failed execution in n8n, fix credential/table/node configuration, then run METROPOLIS_OPERATIONS_ENGINE.',
  missing_inputs: []
}}];
